pub fn component_metadata(id: u16) -> Option<&'static ComponentMetadata> {
    COMPONENTS.iter().find(|metadata| metadata.id == id)
}

pub fn operation_metadata(id: u16) -> Option<&'static OperationMetadata> {
    OPERATIONS.iter().find(|metadata| metadata.id == id)
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::HashSet;

    #[test]
    fn generated_registry_has_unique_ids_and_resolvable_capabilities() {
        let component_ids: HashSet<_> = COMPONENTS.iter().map(|item| item.id).collect();
        let operation_ids: HashSet<_> = OPERATIONS.iter().map(|item| item.id).collect();
        assert_eq!(component_ids.len(), COMPONENTS.len());
        assert_eq!(operation_ids.len(), OPERATIONS.len());
        assert!(OPERATIONS.iter().all(|operation| {
            COMPONENTS
                .iter()
                .any(|component| operation.applies_to(component.id))
        }));
    }

    #[test]
    fn value_kind_layout_matches_the_wire_contract() {
        assert_eq!(ValueKind::None as u16, 0);
        assert_eq!(ValueKind::F32 as u16, 1);
        assert_eq!(ValueKind::U32 as u16, 2);
        assert_eq!(ValueKind::Callback as u16, 3);
        assert_eq!(ValueKind::U64 as u16, 4);
    }
}
